            { Assert.That(anchor,Is.SameAs(_fixtureThread)); Assert.That(atIssue,Is.SameAs(_fixtureThread)); Assert.That(rejectedThread,Is.Not.Null); Assert.That(rejectedThread,Is.Not.SameAs(_fixtureThread)); }
            else
            { Assert.That(rejectedThread,Is.Null); Assert.That(exactCause=="IssuerThreadAnchor" ? anchor : atIssue,Is.Null); Assert.That(exactCause=="IssuerThreadAnchor" ? atIssue : anchor,Is.SameAs(_fixtureThread)); }
