            Assert.That(Field(Router,typeof(InputRouter),"_executionGuardClosed",typeof(bool)),Is.False);
            Assert.That(Field(Adapter,typeof(DesktopProfileLaunchAdapterV1),"_resetReceipt",typeof(ProfileResetMemoryReceiptV1)),Is.Null);
            Assert.That(File.Exists(System.IO.Path.Combine(Root,"profile.reset.json")),Is.False);
            AssertFrozenNoOpSingleCallSource();
            const string bridge="Assets/AcadeGameMaker/Runtime/Input/Unity/ProfileResetExecutionBridgeV1.cs";
            var source=File.ReadAllText(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Application.dataPath),bridge));
            var preEntry=source.IndexOf("if (!TryTrustedExecutionSource(confirmed,adapter,router,null,out var witness,out var lifecycle)",StringComparison.Ordinal);
            var register=source.IndexOf("Executions.Add(confirmed,execution);",preEntry,StringComparison.Ordinal);
