            row.Observe("authorityCorrelation.memoryGeneration",null,"Unknown");
            row.Observe("authorityCorrelation.checked",false,"SourceEstablished",reference);
            row.Observe("authorityCorrelation.proof","Unknown","Unknown");
            row.Observe("authorityCorrelation.c2Result","Unknown","Unknown");
            row.Observe("authorityCorrelation.receipt","Unknown","Unknown");
            row.Observe("authorityCorrelation.nextEpoch","Unknown","Unknown");
            row.Observe("diagnostic.generationUnobservedReason","PreEntryProtocolRejectBeforePayload","SourceEstablished",reference);
            row.Observe("diagnostic.preEntryProtocolRejectBeforePayload","Yes");
