            row.Observe("guard.adapter","NotEntered"); row.Observe("guard.router","NotEntered");
            row.Observe("guard.permanentFaultRecorded","No","SourceEstablished",reference);
            ObserveActualHistory(row,null);
            row.Observe("barrier.state","NoBarrier","SourceEstablished",reference);
            row.Observe("barrier.ordinaryWriterBlocked","Unknown","Unknown");
            row.Observe("barrier.evidenceReference",null,"SourceEstablished",reference);
            row.Observe("diagnostic.barrierEvidenceAbsentReason","NoBarrierEvidenceRequiredForThisPreEntryOrPureRow","SourceEstablished",reference);
            foreach(var key in new[] {"c1Begin","c2Finalize","freshReserve","freshComplete","preparedObserver","c2Observer"})
                row.Observe("callCounts."+key,0L,"SourceEstablished",reference);
