        private static object OriginalField(object actual,Type declaring,string name,Type result)
        {
            var field=declaring.GetField(name,BindingFlags.DeclaredOnly|BindingFlags.Instance|BindingFlags.NonPublic);
            if (field == null || field.DeclaringType != declaring || field.FieldType != result || !field.IsInitOnly || field.IsStatic)
                throw new MissingFieldException("정확 readonly 원본 필드가 아닙니다: "+name);
            return Field(actual,declaring,name,result);
        }
        private static object ReadOriginalTable(Type declaring,string name,Type keyType,Type valueType,object key)
        {
            var tableType=typeof(System.Runtime.CompilerServices.ConditionalWeakTable<,>).MakeGenericType(keyType,valueType);
            var field=declaring.GetField(name,BindingFlags.DeclaredOnly|BindingFlags.Static|BindingFlags.NonPublic);
            if (field == null || field.DeclaringType != declaring || field.FieldType != tableType || !field.IsInitOnly || !field.IsPrivate)
                throw new MissingFieldException("정확 실제 원장 필드가 아닙니다: "+name);
            var method=tableType.GetMethod("TryGetValue",BindingFlags.DeclaredOnly|BindingFlags.Instance|BindingFlags.Public,null,new[] {keyType,valueType.MakeByRefType()},null);
            if (method == null || method.DeclaringType != tableType || method.ReturnType != typeof(bool) || !method.GetParameters()[1].IsOut)
                throw new MissingMethodException("정확 원장 읽기 메서드가 아닙니다.");
            var arguments=new[] {key,null}; Assert.That((bool)method.Invoke(field.GetValue(null),arguments),Is.True);
            Assert.That(arguments[1],Is.Not.Null); Assert.That(arguments[1].GetType(),Is.EqualTo(valueType)); return arguments[1];
        }
        private static void AssertOriginalTableAbsent(Type declaring,string name,Type keyType,Type valueType,object key)
        {
            var tableType=typeof(System.Runtime.CompilerServices.ConditionalWeakTable<,>).MakeGenericType(keyType,valueType);
            var field=declaring.GetField(name,BindingFlags.DeclaredOnly|BindingFlags.Static|BindingFlags.NonPublic);
            if (field == null || field.DeclaringType != declaring || field.FieldType != tableType || !field.IsInitOnly || !field.IsPrivate)
                throw new MissingFieldException("정확 실제 원장 필드가 아닙니다: "+name);
            var method=tableType.GetMethod("TryGetValue",BindingFlags.DeclaredOnly|BindingFlags.Instance|BindingFlags.Public,null,new[] {keyType,valueType.MakeByRefType()},null);
            if (method == null || method.DeclaringType != tableType || method.ReturnType != typeof(bool) || !method.GetParameters()[1].IsOut)
                throw new MissingMethodException("정확 원장 읽기 메서드가 아닙니다.");
            var arguments=new[] {key,null}; Assert.That((bool)method.Invoke(field.GetValue(null),arguments),Is.False);
            Assert.That(arguments[1],Is.Null);
        }
