        internal void ObserveUnreturnedObservedProofCheckpoint(EvidenceRow row,Exception actualFailure,Exception callbackFailure,
            ProfileResetExecutionCheckpointV1 actualCheckpoint,object observedProof,int reached,int c1Returns,int c2Calls,
            int preparedObservers,int c2Observers,int freshReserves)
        {
            if (TestContext.CurrentContext.Test.MethodName != "AC008_ActualC4CheckpointFailureNeverRestoresAuthority" ||
                actualCheckpoint != ProfileResetExecutionCheckpointV1.AfterPreparedProofTake && actualCheckpoint != ProfileResetExecutionCheckpointV1.BeforeC2Finalize)
                throw new ArgumentException("정확 두 준비 증명 경계만 허용합니다.");
