            Assert.That(c1Returns,Is.EqualTo(1)); Assert.That(preparedObservers,Is.EqualTo(1));
            Assert.That(c2Calls,Is.Zero); Assert.That(c2Observers,Is.Zero); Assert.That(freshReserves,Is.Zero);
            var proofType=ProfileType("ProfileResetDiskPreparedProofV1"); Assert.That(observedProof,Is.TypeOf(proofType));
            Assert.That(OriginalField(observedProof,proofType,"_root",typeof(string)),Is.EqualTo(Root));
            var markerType=ProfileType("ValidatedProfileResetBarrierV1");
            var marker=OriginalField(observedProof,proofType,"_expectedMarker",markerType); Assert.That(marker,Is.Not.Null);
            var validateInvariant=proofType.GetMethod("ValidateInvariant",BindingFlags.DeclaredOnly|BindingFlags.Instance|BindingFlags.NonPublic,null,Type.EmptyTypes,null);
