        private static void AssertFrozenBusySource()
        {
            var project=System.IO.Path.GetDirectoryName(Application.dataPath);
            var manifest=JsonUtility.FromJson<FrozenSourceManifest>(File.ReadAllText(System.IO.Path.Combine(project,"artifacts/c4-frozen-source-manifest-v16.json")));
            Assert.That(manifest,Is.Not.Null); Assert.That(manifest.Files,Is.Not.Null);
            var paths=new[] {
                "Assets/AcadeGameMaker/Runtime/Profile/ProfileNewGameResetServiceV1.cs",
                "Assets/AcadeGameMaker/Runtime/Profile/ProfileResetDiskTransactionV1.cs",
                "Assets/AcadeGameMaker/Runtime/Input/Unity/ProfileResetExecutionBridgeV1.cs"};
            var hashes=new[] {
                "23D7248B1A603A89BC8FF0FFDBB24FA04E640A66018DDC5689F97EC80701FBE5",
                "BE0F16834F96272AD68C15F5004E9C37491EEF6F82D7CA728A5E1D1D60CB71E2",
                "52E00FE10FDEAFB8C192CF7F92B2EA428C16A202D640BEAF79C8F58E6704F32A"};
            var texts=new string[3];
            for(var i=0;i<paths.Length;i++)
            {
                FrozenSourceBinding binding=null;
                foreach(var entry in manifest.Files) if(entry.Path==paths[i]) { Assert.That(binding,Is.Null); binding=entry; }
                Assert.That(binding,Is.Not.Null); Assert.That(binding.Kind,Is.EqualTo("Runtime")); Assert.That(binding.Sha256,Is.EqualTo(hashes[i]));
                var bytes=File.ReadAllBytes(System.IO.Path.Combine(project,paths[i]));
                using(var sha=System.Security.Cryptography.SHA256.Create()) Assert.That(BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-",""),Is.EqualTo(binding.Sha256));
                texts[i]=System.Text.Encoding.UTF8.GetString(bytes).Replace("\r\n","\n");
            }
            Assert.That(texts[0].Contains("new FileStream(path, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None)"),Is.True);
            Assert.That(texts[0].Contains("throw new ProfileRootOperationBlockedExceptionV1(ProfileRootOperationOutcomeV1.Busy"),Is.True);
            Assert.That(texts[1].Contains("using (var lease = ProfileRootOperationLockV1.Acquire(normalized))"),Is.True);
            Assert.That(texts[1].Contains("NoAuthorityResult(ProfileResetDiskOutcomeV1.Busy, ProfileResetDurableStateV1.NoBarrier"),Is.True);
            var begin=texts[2].IndexOf("var disk=ProfileResetDiskTransactionV1.Begin(",StringComparison.Ordinal);
            var branch=texts[2].IndexOf("var fresh=outcome == ProfileResetExecutionOutcomeV1.Busy",begin,StringComparison.Ordinal);
            var checkpoint=texts[2].IndexOf("ProfileResetExecutionCheckpointV1.BeforeFreshHandbackPublish",begin,StringComparison.Ordinal);
            Assert.That(begin,Is.GreaterThanOrEqualTo(0)); Assert.That(branch,Is.GreaterThan(begin)); Assert.That(checkpoint,Is.GreaterThan(branch));
        }
