        internal void ObserveActualResult(EvidenceRow row,ProfileResetExecutionResultV1 actualResult)
        { ObserveActualResult(row,actualResult,Confirmed); }
        internal void ObserveActualResult(EvidenceRow row,ProfileResetExecutionResultV1 actualResult,ConfirmedProfileResetRequestV1 actualConfirmed)
        {
            var resultRecord=ReadActualResultRecord(actualResult,actualConfirmed); var resultType=resultRecord.GetType();
            var execution=ReadActualExecutionRecord(actualConfirmed); var executionType=execution.GetType();
            var witness=ReadConfirmedWitness(actualConfirmed); var lifecycle=ReadRequestLifecycle(actualConfirmed); var issue=ReadOriginalRequestIssue(actualConfirmed);
            Assert.That(OriginalField(execution,executionType,"Confirmed",typeof(ConfirmedProfileResetRequestV1)),Is.SameAs(actualConfirmed));
            Assert.That(OriginalField(execution,executionType,"Witness",witness.GetType()),Is.SameAs(witness));
            Assert.That(OriginalField(execution,executionType,"Lifecycle",lifecycle.GetType()),Is.SameAs(lifecycle));
            Assert.That(OriginalField(issue,issue.GetType(),"Request",typeof(ConfirmedProfileResetRequestV1)),Is.SameAs(actualConfirmed));
            Assert.That(OriginalField(execution,executionType,"Adapter",typeof(DesktopProfileLaunchAdapterV1)),Is.SameAs(Adapter));
            Assert.That(OriginalField(execution,executionType,"Router",typeof(InputRouter)),Is.SameAs(Router));
            Assert.That(OriginalField(execution,executionType,"Owner",typeof(object)),Is.SameAs(Owner));
            Assert.That(OriginalField(execution,executionType,"Root",typeof(string)),Is.EqualTo(Root));
            Assert.That(OriginalField(execution,executionType,"Thread",typeof(Thread)),Is.SameAs(Thread.CurrentThread));
            var generation=(long)OriginalField(execution,executionType,"Generation",typeof(long));
            Assert.That(actualResult.ExecutionGeneration,Is.EqualTo(generation)); Assert.That(generation,Is.GreaterThan(0));
            foreach (var key in new[] {"confirmed","owner","adapter","router","root"}) row.Observe("authorityCorrelation."+key,"SameActual");
            row.Observe("authorityCorrelation.executionGeneration",generation);
            row.Observe("diagnostic.executionGenerationSameActualCwt","Yes");
            var diskType=ProfileType("ProfileResetDiskResultV1");
            var disk=OriginalField(resultRecord,resultType,"Disk",diskType);
            var proofType=ProfileType("ProfileResetDiskPreparedProofV1");
            var proof=OriginalField(disk,diskType,"_proof",proofType);
            row.Observe("authorityCorrelation.proof",proof == null ? "Absent" : "SameActual");
            var memory=(ProfileResetMemoryResultV1)OriginalField(resultRecord,resultType,"Memory",typeof(ProfileResetMemoryResultV1));
            var receipt=(ProfileResetMemoryReceiptV1)OriginalField(resultRecord,resultType,"Receipt",typeof(ProfileResetMemoryReceiptV1));
            row.Observe("authorityCorrelation.c2Result",memory == null ? "Absent" : "SameActual");
            row.Observe("authorityCorrelation.receipt",receipt == null ? "Absent" : "SameActual");
            if (receipt == null)
            {
                Assert.That(memory == null || memory.Receipt == null,Is.True);
                row.Observe("authorityCorrelation.memoryGeneration",null);
                row.Observe("diagnostic.memoryGenerationAuthorityAbsent","Yes");
            }
            else
            {
                receipt.Validate(); Assert.That(memory,Is.Not.Null); memory.Validate(); Assert.That(memory.Receipt,Is.SameAs(receipt));
                var receiptType=typeof(ProfileResetMemoryReceiptV1); var receiptWitnessType=receiptType.GetNestedType("Witness",BindingFlags.NonPublic);
                var receiptWitness=ReadOriginalTable(receiptType,"Witnesses",receiptType,receiptWitnessType,receipt);
                var memoryGeneration=(long)OriginalField(receiptWitness,receiptWitnessType,"Generation",typeof(long));
                Assert.That(memoryGeneration,Is.GreaterThan(0)); Assert.That(receipt.Generation,Is.EqualTo(memoryGeneration));
                Assert.That(OriginalField(receiptWitness,receiptWitnessType,"Root",typeof(string)),Is.EqualTo(Root));
                row.Observe("authorityCorrelation.memoryGeneration",memoryGeneration);
                row.Observe("diagnostic.memoryGenerationSameActualCwt","Yes");
            }
            row.Observe("authorityCorrelation.checked",true);
            var epochToken=OriginalField(execution,executionType,"Epoch",typeof(object));
            var ownerType=Hub("NewGameConfirmationOwnerV1");
            var freshHistoryType=ownerType.GetNestedType("ExecutionFreshHistory",BindingFlags.NonPublic);
            var freshHistory=Field(Owner,ownerType,"_executionFreshHistory",freshHistoryType);
            var lowerFreshType=typeof(ProfileNewGameConfirmationV1).GetNestedType("FreshRecord",BindingFlags.NonPublic);
            var lowerFresh=Field(resultRecord,resultType,"Reservation",lowerFreshType);
            var handback=OriginalField(resultRecord,resultType,"Handback",typeof(ProfileResetFreshC3HandbackV1));
            if (handback != null)
                Assert.That(ReadOriginalTable(typeof(ProfileNewGameConfirmationV1),"FreshHandbacks",typeof(ProfileResetFreshC3HandbackV1),resultType,handback),Is.SameAs(resultRecord));
            var hasNextEpoch=lowerFresh != null;
            object nextToken=null;
            if (lowerFresh != null)
            {
                Assert.That(handback,Is.Not.Null);
                Assert.That(OriginalField(lowerFresh,lowerFreshType,"Result",resultType),Is.SameAs(resultRecord));
                var reservation=OriginalField(lowerFresh,lowerFreshType,"Reservation",typeof(ProfileResetFreshExecutionReservationV1));
                Assert.That(ReadOriginalTable(typeof(ProfileNewGameConfirmationV1),"ExecutionReservations",typeof(ProfileResetFreshExecutionReservationV1),lowerFreshType,reservation),Is.SameAs(lowerFresh));
                nextToken=OriginalField(lowerFresh,lowerFreshType,"NextToken",typeof(object));
                Assert.That(nextToken,Is.Not.Null); Assert.That(nextToken,Is.Not.SameAs(epochToken));
                Assert.That(OriginalField(lowerFresh,lowerFreshType,"NextEpoch",typeof(long)),Is.EqualTo(checked((long)OriginalField(execution,executionType,"InteractionGeneration",typeof(long))+1)));
            }
            var operationType=ownerType.GetNestedType("FreshOperation",BindingFlags.NonPublic);
            var operation=Field(Owner,ownerType,"_executionFresh",operationType);
            if (freshHistory != null)
            {
                var historical=OriginalField(freshHistory,freshHistoryType,"Operation",operationType);
                if (ReferenceEquals(OriginalField(historical,operationType,"Result",typeof(ProfileResetExecutionResultV1)),actualResult)) operation=historical;
            }
            if (operation != null && ReferenceEquals(OriginalField(operation,operationType,"Result",typeof(ProfileResetExecutionResultV1)),actualResult))
            {
                var capType=Hub("HubNewGameExecutionFreshCapabilityV1"); var cap=OriginalField(operation,operationType,"Capability",capType);
                var parent=TestContext.CurrentContext.Test.MethodName;
                var beforeOwnerRegistration=(parent=="AC004_FreshPartialFailureClosesBothSlots" || parent=="AC008_ActualC4CheckpointFailureNeverRestoresAuthority") &&
                    (row.ExactCheckpointValue == 19 || row.ExactCheckpointValue == 20);
                if (beforeOwnerRegistration)
                    AssertOriginalTableAbsent(ownerType,"ExecutionFreshCapabilities",capType,operationType,cap);
                else
                    Assert.That(ReadOriginalTable(ownerType,"ExecutionFreshCapabilities",capType,operationType,cap),Is.SameAs(operation));
                Assert.That(OriginalField(operation,operationType,"Owner",ownerType),Is.SameAs(Owner));
                Assert.That(OriginalField(operation,operationType,"Thread",typeof(Thread)),Is.SameAs(Thread.CurrentThread));
                var commitType=ownerType.GetNestedType("CommitHistory",BindingFlags.NonPublic);
                var original=OriginalField(operation,operationType,"Original",commitType);
                Assert.That(OriginalField(original,commitType,"Token",typeof(object)),Is.SameAs(epochToken));
                var ownerNext=OriginalField(operation,operationType,"Token",typeof(object));
                Assert.That(ownerNext,Is.Not.Null);
                if (nextToken != null) Assert.That(ownerNext,Is.SameAs(nextToken));
                Assert.That(OriginalField(operation,operationType,"Epoch",typeof(long)),Is.EqualTo(checked((long)OriginalField(original,commitType,"Epoch",typeof(long))+1)));
                hasNextEpoch=true;
            }
            row.Observe("authorityCorrelation.nextEpoch",hasNextEpoch ? "SameActual" : "Absent");
