        internal void ObserveActualGuard(EvidenceRow row,ConfirmedProfileResetRequestV1 actualConfirmed)
        {
            var execution=ReadActualExecutionRecord(actualConfirmed); Assert.That(execution,Is.Not.Null); var executionType=execution.GetType();
            Assert.That(OriginalField(execution,executionType,"Thread",typeof(Thread)),Is.SameAs(Thread.CurrentThread));
            var context=OriginalField(execution,executionType,"Guard",typeof(ProfileResetExecutionGuardContextV1));
            foreach (var adapterHalf in new[] {true,false})
            {
                var declaring=adapterHalf ? typeof(DesktopProfileLaunchAdapterV1) : typeof(InputRouter);
                var receiver=adapterHalf ? (object)Adapter : Router;
                var halfType=declaring.GetNestedType("ExecutionGuardHalf",BindingFlags.NonPublic);
                var tableType=typeof(System.Runtime.CompilerServices.ConditionalWeakTable<,>).MakeGenericType(declaring,halfType);
                var table=declaring.GetField("ExecutionGuardHalves",BindingFlags.DeclaredOnly|BindingFlags.Static|BindingFlags.NonPublic);
                Assert.That(table,Is.Not.Null); Assert.That(table.IsInitOnly,Is.True); Assert.That(table.FieldType,Is.EqualTo(tableType));
                var get=tableType.GetMethod("TryGetValue",BindingFlags.DeclaredOnly|BindingFlags.Instance|BindingFlags.Public,null,new[] {declaring,halfType.MakeByRefType()},null);
                Assert.That(get,Is.Not.Null); Assert.That(get.DeclaringType,Is.EqualTo(tableType)); Assert.That(get.ReturnType,Is.EqualTo(typeof(bool))); Assert.That(get.GetParameters()[1].IsOut,Is.True);
                var arguments=new[] {receiver,null}; var found=(bool)get.Invoke(table.GetValue(null),arguments);
                var entered=(bool)Field(execution,executionType,adapterHalf ? "AdapterEntered" : "RouterEntered",typeof(bool));
                string status;
                if (!found) { Assert.That(entered,Is.False); status="NotEntered"; }
                else
                {
                    var current=arguments[1]; var original=current;
                    for (var remaining=0;original != null && !ReferenceEquals(OriginalField(original,halfType,"Context",typeof(ProfileResetExecutionGuardContextV1)),context) && remaining<8;remaining++)
                        original=OriginalField(original,halfType,"Previous",halfType);
                    Assert.That(original,Is.Not.Null);
                    Assert.That(OriginalField(original,halfType,"Context",typeof(ProfileResetExecutionGuardContextV1)),Is.SameAs(context));
                    var closed=(bool)OriginalField(original,halfType,"Closed",typeof(bool));
                    var blocked=(bool)OriginalField(original,halfType,"Blocked",typeof(bool));
                    if (ReferenceEquals(original,current))
                    { Assert.That(Field(receiver,declaring,"_executionGuardClosed",typeof(bool)),Is.EqualTo(closed)); Assert.That(Field(receiver,declaring,"_executionGuardBlocked",typeof(bool)),Is.EqualTo(blocked)); }
                    if (closed) status="Closed";
                    else if (blocked) { Assert.That(entered,Is.True); status="Entered"; }
                    else { Assert.That((bool)Field(execution,executionType,adapterHalf ? "AdapterFreshCompleted" : "RouterFreshCompleted",typeof(bool)),Is.True); status="CompletedFresh"; }
                }
                row.Observe(adapterHalf ? "guard.adapter" : "guard.router",status);
            }
            var eventType=typeof(ProfileNewGameConfirmationV1).GetNestedType("ExecutionEvent",BindingFlags.NonPublic);
            var fault=Field(execution,executionType,"FaultHistory",eventType) != null || ReferenceEquals(Field(execution,executionType,"Head",eventType),OriginalField(execution,executionType,"Failure",eventType));
            row.Observe("guard.permanentFaultRecorded",fault ? "Yes" : "No");
        }
