        private static void AssertFrozenOrdinaryWriterSource()
        {
            var project=System.IO.Path.GetDirectoryName(Application.dataPath);
            const string savePath="Assets/AcadeGameMaker/Runtime/Profile/ProfileAtomicSaveServiceV1.cs";
            const string barrierPath="Assets/AcadeGameMaker/Runtime/Profile/ProfileNewGameResetServiceV1.cs";
            var paths=new[] {savePath,barrierPath};
            var hashes=new[] {"80DDBF925C74A8A81DD3B3950F25B3843D76B81F62ED942F3F3585CFB52B3F87","23D7248B1A603A89BC8FF0FFDBB24FA04E640A66018DDC5689F97EC80701FBE5"};
            var manifest=JsonUtility.FromJson<FrozenSourceManifest>(File.ReadAllText(System.IO.Path.Combine(project,"artifacts/c4-frozen-source-manifest-v1.json")));
            Assert.That(manifest,Is.Not.Null); Assert.That(manifest.SchemaVersion,Is.EqualTo(1)); Assert.That(manifest.Files,Is.Not.Null);
            Assert.That(manifest.Count,Is.EqualTo(manifest.Files.Length)); Assert.That(manifest.WholeAccepted,Is.False);
            var texts=new string[2];
            for (var i=0;i<paths.Length;i++)
            {
                FrozenSourceBinding found=null;
                foreach (var binding in manifest.Files) if (binding.Path == paths[i]) { Assert.That(found,Is.Null); found=binding; }
                Assert.That(found,Is.Not.Null); Assert.That(found.Kind,Is.EqualTo("Runtime")); Assert.That(found.Sha256,Is.EqualTo(hashes[i]));
                var bytes=File.ReadAllBytes(System.IO.Path.Combine(project,paths[i]));
                using (var sha=System.Security.Cryptography.SHA256.Create()) Assert.That(BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-",""),Is.EqualTo(found.Sha256));
                texts[i]=System.Text.Encoding.UTF8.GetString(bytes).Replace("\r\n","\n");
            }
            Assert.That(texts[0].Contains("using (ProfileRootOperationLockV1.Acquire(normalized))\n            {\n                ProfileResetBarrierV1.ThrowIfPresent(normalized);\n                return Save(normalized, document, ProfileAtomicSaveBclFileOperations.Instance);"),Is.True);
            Assert.That(texts[1].Contains("var attributes = File.GetAttributes(path);"),Is.True);
        }
        internal void ObserveActualBarrier(EvidenceRow row,ProfileResetExecutionResultV1 actualResult,RootLeaseWorker actualWorker=null)
        { ObserveActualBarrier(row,actualResult,actualWorker,Confirmed); }
        internal void ObserveActualBarrier(EvidenceRow row,ProfileResetExecutionResultV1 actualResult,RootLeaseWorker actualWorker,ConfirmedProfileResetRequestV1 actualConfirmed)
        {
            var resultRecord=ReadActualResultRecord(actualResult,actualConfirmed); var resultType=resultRecord.GetType();
            var diskType=ProfileType("ProfileResetDiskResultV1"); var disk=OriginalField(resultRecord,resultType,"Disk",diskType);
            var validate=diskType.GetMethod("Validate",BindingFlags.DeclaredOnly|BindingFlags.Instance|BindingFlags.Public,null,Type.EmptyTypes,null);
            Assert.That(validate,Is.Not.Null); Assert.That(validate.DeclaringType,Is.EqualTo(diskType)); Assert.That(validate.ReturnType,Is.EqualTo(typeof(void)));
            try { validate.Invoke(disk,null); } catch(TargetInvocationException error) { if(error.InnerException != null) throw error.InnerException; throw; }
            var state=(ProfileResetDurableStateV1)OriginalField(disk,diskType,"_state",typeof(ProfileResetDurableStateV1));
            var receipt=(ProfileResetMemoryReceiptV1)OriginalField(resultRecord,resultType,"Receipt",typeof(ProfileResetMemoryReceiptV1));
            if (receipt != null) receipt.Validate();
            bool barrierPresent;
            try { File.GetAttributes(System.IO.Path.Combine(Root,"profile.reset.json")); barrierPresent=true; }
            catch (FileNotFoundException) { barrierPresent=false; }
            catch (DirectoryNotFoundException) { Assert.That(Directory.Exists(Root),Is.True); barrierPresent=false; }
            var leaseHeld=actualWorker != null && !actualWorker.LeaseReleased;
            var barrierState=state == ProfileResetDurableStateV1.DefaultCommitUncertain ? "Uncertain" :
                barrierPresent || leaseHeld ? "DurableBarrier" : "NoBarrier";
            AssertFrozenOrdinaryWriterSource();
            var reference="source:Assets/AcadeGameMaker/Runtime/Profile/ProfileAtomicSaveServiceV1.cs:"+(barrierPresent ? "170" : "168");
            row.Observe("barrier.state",barrierState);
            if (TestContext.CurrentContext.Test.MethodName == "AC006_ActualOrdinaryWriterCannotCrossPreparedBarrier")
            {
                Assert.That(row.HasObserved("diagnostic.actualOrdinaryWriterBlocked","Yes"),Is.True);
                return; // 실제 저장 결과와 원본 바이트 검사는 부모 시험이 최종 행에 기록한다.
            }
            if (barrierPresent || leaseHeld)
            {
                row.Observe("barrier.ordinaryWriterBlocked","Yes","SourceEstablished",reference);
                row.Observe("barrier.evidenceReference",reference,"SourceEstablished",reference);
                row.Observe("diagnostic.barrierEvidenceKind","FrozenSourceBoundary","SourceEstablished",reference);
                return;
            }
            var pointers=FrozenNoSameCaseSavePointers();
            row.Observe("barrier.ordinaryWriterBlocked","Unknown","Unknown");
            row.Observe("barrier.evidenceReference",pointers.Item2,"SourceEstablished",pointers.Item2);
            row.Observe("diagnostic.barrierEvidenceKind","FrozenSourceBoundary","SourceEstablished",pointers.Item2);
            row.Observe("diagnostic.ordinaryWriterObservation","NoSameCaseSaveObservation","SourceEstablished",pointers.Item1);
        }
        private static Tuple<string,string> FrozenNoSameCaseSavePointers(bool preC1=false,string fixtureMethod=null,string fixtureReadNeedle=null)
        {
            var project=System.IO.Path.GetDirectoryName(Application.dataPath);
            const string parent="Assets/AcadeGameMaker/Tests/EditMode/InputUnity/ProfileResetExecutionBridgeV1Tests.cs";
            const string fixture="Assets/AcadeGameMaker/Tests/EditMode/InputUnity/C4ActualExecutionEditFixtureV1.cs";
            var manifest=JsonUtility.FromJson<FrozenSourceManifest>(File.ReadAllText(System.IO.Path.Combine(project,"artifacts/c4-frozen-source-manifest-v16.json")));
            Assert.That(manifest,Is.Not.Null); Assert.That(manifest.Files,Is.Not.Null);
            string[] paths={parent,fixture}; var pointers=new string[2];
            for(var p=0;p<paths.Length;p++)
            {
                FrozenSourceBinding binding=null;
                foreach(var candidate in manifest.Files) if(candidate.Path == paths[p]) { Assert.That(binding,Is.Null); binding=candidate; }
                Assert.That(binding,Is.Not.Null);
                var bytes=File.ReadAllBytes(System.IO.Path.Combine(project,paths[p]));
                using(var sha=System.Security.Cryptography.SHA256.Create()) Assert.That(BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-",""),Is.EqualTo(binding.Sha256));
                var lines=File.ReadAllLines(System.IO.Path.Combine(project,paths[p])); var line=0;
                var needle=p==0 ? "public void "+TestContext.CurrentContext.Test.MethodName+"(" :
                    fixtureReadNeedle ?? (preC1 ? "try { File.GetAttributes(System.IO.Path.Combine(Root,\"profile.reset.json\")); marker=true; }" :
                    "try { File.GetAttributes(System.IO.Path.Combine(Root,\"profile.reset.json\")); barrierPresent=true; }");
                if(p==0)
                {
                    var first=-1;
                    for(var i=0;i<lines.Length;i++)
                        if(lines[i].TrimStart().StartsWith(needle,StringComparison.Ordinal)) { Assert.That(first,Is.EqualTo(-1)); first=i; }
                    Assert.That(first,Is.GreaterThanOrEqualTo(0));
                    line=first+1;
                    var last=lines.Length;
                    for(var i=first+1;i<lines.Length;i++)
                        if(lines[i].StartsWith("        [Test",StringComparison.Ordinal) || lines[i].StartsWith("        public void ",StringComparison.Ordinal) || lines[i].StartsWith("        private ",StringComparison.Ordinal)) { last=i; break; }
                    var body=string.Join("\n",lines,first,last-first);
                    Assert.That(body.Contains("ProfileAtomicSaveServiceV1.Save("),Is.False);
                }
                else
                {
                    var exactMethod=fixtureMethod ?? (preC1 ? "ObservePreC1Failure" : "ObserveActualBarrier");
                    for(var first=0;first<lines.Length;first++)
                    {
                        if(!lines[first].TrimStart().StartsWith("internal void "+exactMethod+"(",StringComparison.Ordinal)) continue;
                        var last=lines.Length;
                        for(var i=first+1;i<lines.Length;i++)
                            if(lines[i].StartsWith("        internal ",StringComparison.Ordinal) || lines[i].StartsWith("        private ",StringComparison.Ordinal)) { last=i; break; }
                        for(var i=first+1;i<last;i++)
                            if(lines[i].TrimStart().StartsWith(needle,StringComparison.Ordinal)) { Assert.That(line,Is.Zero); line=i+1; }
                    }
                    Assert.That(line,Is.GreaterThan(0));
                }
                pointers[p]="source:"+paths[p]+":"+line;
            }
            return Tuple.Create(pointers[0],pointers[1]);
        }
