            var freshType=typeof(ProfileNewGameConfirmationV1).GetNestedType("FreshRecord",BindingFlags.NonPublic);
            var fresh=Field(result,resultType,"Reservation",freshType);
            Assert.That(Field(execution,executionType,"FaultHistory",eventType),Is.Not.Null);
            Assert.That(Field(result,resultType,"FreshHead",eventType),Is.SameAs(OriginalField(result,resultType,"FreshFailure",eventType)));
            Assert.That(Field(result,resultType,"FreshClosedHistory",eventType),Is.Not.Null);
            Assert.That(fresh == null,Is.EqualTo(checkpoint == 19));
            if (fresh != null)
            {
                Assert.That(OriginalField(fresh,freshType,"Result",resultType),Is.SameAs(result));
                var reservation=OriginalField(fresh,freshType,"Reservation",typeof(ProfileResetFreshExecutionReservationV1));
                Assert.That(ReadOriginalTable(typeof(ProfileNewGameConfirmationV1),"ExecutionReservations",typeof(ProfileResetFreshExecutionReservationV1),freshType,reservation),Is.SameAs(fresh));
                Assert.That(Field(result,resultType,"FreshClosedHistory",eventType),Is.Not.SameAs(OriginalField(fresh,freshType,"Completed",eventType)));
            }
            var ownerType=Hub("NewGameConfirmationOwnerV1"); var operationType=ownerType.GetNestedType("FreshOperation",BindingFlags.NonPublic);
            var operation=Field(Owner,ownerType,"_executionFresh",operationType);
            Assert.That(operation,Is.Not.Null);
            Assert.That(OriginalField(operation,operationType,"Result",typeof(ProfileResetExecutionResultV1)),Is.SameAs(actualResult));
            if (checkpoint <= 20)
                Assert.That(Field(operation,operationType,"LowerReservation",typeof(ProfileResetFreshExecutionReservationV1)),Is.Null);
            if (checkpoint >= 21)
                Assert.That(Field(operation,operationType,"LowerReservation",typeof(ProfileResetFreshExecutionReservationV1)),Is.SameAs(OriginalField(fresh,freshType,"Reservation",typeof(ProfileResetFreshExecutionReservationV1))));
            var historyType=ownerType.GetNestedType("ExecutionFreshHistory",BindingFlags.NonPublic);
            Assert.That(Field(Owner,ownerType,"_executionFreshHistory",historyType),Is.Null);
