        internal sealed class RootLeaseWorker : IDisposable
        {
            private readonly ManualResetEventSlim _ready=new ManualResetEventSlim(false), _release=new ManualResetEventSlim(false);
            private readonly Thread _worker;
            private readonly string _root;
            private Exception _failure;
            private bool _acquired;
            internal bool LeaseReleased, Joined;
            private bool _releaseWasSignaled;
            internal bool ReleaseSignaled { get { return _releaseWasSignaled; } }
            internal bool HoldsRootAtCheckpoint(string root)
            { return string.Equals(_root,root,StringComparison.Ordinal) && _ready.IsSet && _acquired && _failure == null && _worker.IsAlive && !_release.IsSet && !LeaseReleased; }
            internal bool AcquiredOriginalRoot(string root)
            { return string.Equals(_root,root,StringComparison.Ordinal) && _acquired; }
            internal RootLeaseWorker(string root)
            {
                _root=root;
                var type=ProfileType("ProfileRootOperationLockV1");
                var acquire=type.GetMethod("Acquire",BindingFlags.DeclaredOnly|BindingFlags.Static|BindingFlags.NonPublic,null,new[] {typeof(string)},null);
                if (acquire == null || acquire.DeclaringType != type || acquire.ReturnType != type || acquire.IsGenericMethod)
                    throw new MissingMethodException("Exact actual root lease binding failed.");
                _worker=new Thread(()=>
                {
                    IDisposable lease=null;
                    try
                    {
                        lease=(IDisposable)acquire.Invoke(null,new object[] {root}); _acquired=lease != null; _ready.Set();
                        if (!_release.Wait(TimeSpan.FromSeconds(60))) throw new TimeoutException("실제 root 작업자의 해제 신호가 없었습니다.");
                    }
                    catch (Exception error) { _failure=error; _ready.Set(); }
                    finally { try { if (lease != null) { lease.Dispose(); LeaseReleased=true; } } catch (Exception error) { _failure=error; } }
                });
                _worker.IsBackground=true; _worker.Start();
                try { if (!_ready.Wait(TimeSpan.FromSeconds(10))) throw new TimeoutException("실제 root lease 준비 제한 시간을 넘었습니다."); if (_failure != null) throw _failure; }
                catch { Dispose(); throw; }
            }
            public void Dispose()
            {
                _release.Set(); _releaseWasSignaled=_release.IsSet; Joined=_worker.Join(TimeSpan.FromSeconds(10));
                if (!Joined) throw new TimeoutException("실제 root 작업자 종료를 수거하지 못했습니다.");
                _ready.Dispose(); _release.Dispose();
                if (_failure != null) throw _failure;
            }
        }
        // AC-M5D7QC4-001..010: 시험이 실제 관측한 값만 공유 규약에 기록한다.
        internal sealed class EvidenceRow
        {
            private readonly string _id, _case, _kind, _family, _checkpoint;
            private readonly string[] _requirements, _acceptance;
            private readonly int? _checkpointValue;
            private readonly System.Collections.Generic.Dictionary<string,object> _authority=new System.Collections.Generic.Dictionary<string,object>(StringComparer.Ordinal);
            private readonly System.Collections.Generic.Dictionary<string,object> _guard=new System.Collections.Generic.Dictionary<string,object>(StringComparer.Ordinal);
            private readonly System.Collections.Generic.Dictionary<string,object> _barrier=new System.Collections.Generic.Dictionary<string,object>(StringComparer.Ordinal);
            private readonly System.Collections.Generic.Dictionary<string,object> _history=new System.Collections.Generic.Dictionary<string,object>(StringComparer.Ordinal);
            private readonly System.Collections.Generic.Dictionary<string,object> _cleanup=new System.Collections.Generic.Dictionary<string,object>(StringComparer.Ordinal);
            private readonly System.Collections.Generic.Dictionary<string,object> _calls=new System.Collections.Generic.Dictionary<string,object>(StringComparer.Ordinal);
            private readonly System.Collections.Generic.Dictionary<string,object> _facts=new System.Collections.Generic.Dictionary<string,object>(StringComparer.Ordinal);
            private readonly System.Collections.Generic.List<string> _diagnostics=new System.Collections.Generic.List<string>();
            private bool _reached, _ended;
            internal string Outcome, Phase;
            internal string Applicability="Required";
            private static readonly string[] CanonicalKeys={
                "authorityCorrelation.confirmed","authorityCorrelation.owner","authorityCorrelation.adapter","authorityCorrelation.router","authorityCorrelation.root","authorityCorrelation.proof","authorityCorrelation.c2Result","authorityCorrelation.receipt","authorityCorrelation.executionGeneration","authorityCorrelation.memoryGeneration","authorityCorrelation.nextEpoch","authorityCorrelation.checked",
                "guard.adapter","guard.router","guard.permanentFaultRecorded","barrier.state","barrier.ordinaryWriterBlocked","barrier.evidenceReference",
                "history.originalCommitPreserved","history.originalEpochPreserved","history.oldTakePreserved","history.oldCursorPreserved","history.receiptReferencePreserved",
                "cleanup.required","cleanup.releaseSignaled","cleanup.workerLeaseReleased","cleanup.workerJoined","cleanup.originalThreadCleanup","cleanup.exception",
                "callCounts.c1Begin","callCounts.c2Finalize","callCounts.freshReserve","callCounts.freshComplete","callCounts.preparedObserver","callCounts.c2Observer","callCounts.nativeCallback"};
            internal EvidenceRow(string id,string[] requirements,string[] acceptance,string kind,string checkpointFamily,string checkpointName,int? checkpointValue)
            {
                _id=id; _case=TestContext.CurrentContext.Test.FullName; _requirements=requirements; _acceptance=acceptance;
                _kind=kind; _family=checkpointFamily; _checkpoint=checkpointName; _checkpointValue=checkpointValue;
                foreach (var key in CanonicalKeys)
                {
                    var value=key.EndsWith("Generation",StringComparison.Ordinal) || key.StartsWith("callCounts.",StringComparison.Ordinal) || key.EndsWith(".evidenceReference",StringComparison.Ordinal) || key.EndsWith(".exception",StringComparison.Ordinal) ? null :
                        key.EndsWith(".checked",StringComparison.Ordinal) || key == "cleanup.required" ? (object)false : "Unknown";
                    Put(key,value,"Unknown",null);
                }
                Emit("Planned",false,null);
            }
            internal void Observe(string path,object actual,string certainty="Observed",string evidenceReference=null)
            {
                if (_ended) throw new InvalidOperationException("종료한 관측 행은 변경할 수 없습니다.");
                if (actual is int) actual=(long)(int)actual;
                if (actual != null && !(actual is string) && !(actual is bool) && !(actual is long)) throw new ArgumentException("관측 leaf는 문자열·bool·Int64·null만 허용합니다.");
                if (certainty != "Observed" && certainty != "SourceEstablished" && certainty != "Unknown") throw new ArgumentException("정확 certainty가 아닙니다.");
                if (System.Array.IndexOf(CanonicalKeys,path)<0)
                {
                    if (!System.Text.RegularExpressions.Regex.IsMatch(path,@"^diagnostic\.[A-Za-z][A-Za-z0-9_]*$")) throw new ArgumentException("정확 진단 경로가 아닙니다.");
                    if (!_facts.ContainsKey(path)) _diagnostics.Add(path);
                }
                Put(path,actual,certainty,evidenceReference);
            }
            internal bool HasObserved(string path,string expected)
            {
                object raw;
                if (!_facts.TryGetValue(path,out raw) || !(raw is System.Collections.Generic.Dictionary<string,object> fact)) return false;
                return Equals(fact["value"],expected) && Equals(fact["certainty"],"Observed");
            }
            internal int? ExactCheckpointValue { get { return _checkpointValue; } }
            internal void Reached()
            {
                if (_ended || _reached) throw new InvalidOperationException("관측 지점은 한 번만 기록합니다.");
                _reached=true; Emit("Reached",true,null);
            }
            internal void Finish()
            {
                if (_ended) throw new InvalidOperationException("관측 행은 이미 종료했습니다.");
                _ended=true;
                var passed=TestContext.CurrentContext.Result.Outcome.Status == NUnit.Framework.Interfaces.TestStatus.Passed;
                Emit(_reached ? passed ? "Passed" : "Failed" : "NotReached",_reached,passed ? null : "부모 실제 NUnit 사례 실패");
            }
            private void Put(string path,object value,string certainty,string reference)
            {
                var split=path.IndexOf('.'); var group=path.Substring(0,split); var leaf=path.Substring(split+1);
                var target=group=="authorityCorrelation" ? _authority : group=="guard" ? _guard : group=="barrier" ? _barrier : group=="history" ? _history : group=="cleanup" ? _cleanup : group=="callCounts" ? _calls : null;
                if (target != null) target[leaf]=value;
                _facts[path]=new System.Collections.Generic.Dictionary<string,object>{{"name",path},{"value",Canonical(value)},{"certainty",certainty},{"evidenceReference",reference}};
            }
            private static string Canonical(object value)
            { return value == null ? "null" : value is bool ? ((bool)value ? "true" : "false") : value is long ? ((long)value).ToString(System.Globalization.CultureInfo.InvariantCulture) : (string)value; }
            private void Emit(string status,bool reached,string failure)
            {
                var facts=new System.Collections.Generic.List<object>();
                foreach (var key in CanonicalKeys) facts.Add(_facts[key]);
                foreach (var key in _diagnostics) facts.Add(_facts[key]);
                var snapshot=new System.Collections.Generic.Dictionary<string,object>{{"snapshotSha256",null},{"facts",facts}};
                var row=new System.Collections.Generic.Dictionary<string,object>{{"id",_id},{"schemaVersion",1L},{"requirementIds",Strings(_requirements)},{"acceptanceIds",Strings(_acceptance)},
                    {"expectedCase",_case},{"status",status},{"actualEvidenceKind",_kind},{"checkpointFamily",_family},{"checkpointName",_checkpoint},{"checkpointValue",_checkpointValue.HasValue ? (object)(long)_checkpointValue.Value : null},
                    {"outcome",Outcome},{"phase",Phase},{"applicability",Applicability},{"reached",reached},
                    {"before",new System.Collections.Generic.Dictionary<string,object>{{"snapshotSha256",null},{"facts",new System.Collections.Generic.List<object>()}}},{"after",snapshot},
                    {"callCounts",_calls},{"authorityCorrelation",_authority},{"guard",_guard},{"barrier",_barrier},{"history",_history},{"cleanup",_cleanup},{"failureReason",failure}};
                TestContext.Out.WriteLine(WriteJson(row));
            }
            private static System.Collections.Generic.List<object> Strings(string[] values)
            { var result=new System.Collections.Generic.List<object>(); foreach(var value in values) result.Add(value); return result; }
            private static string WriteJson(object value)
            {
                if (value == null) return "null";
                var text=value as string;
                if (text != null)
                {
                    var output=new System.Text.StringBuilder("\"");
                    foreach(var character in text)
                    { if(character=='"'||character=='\\') output.Append('\\').Append(character); else if(character<32) output.Append("\\u").Append(((int)character).ToString("x4",System.Globalization.CultureInfo.InvariantCulture)); else output.Append(character); }
                    return output.Append('"').ToString();
                }
                if (value is bool || value is long) return Canonical(value);
                var dictionary=value as System.Collections.Generic.Dictionary<string,object>;
                if (dictionary != null)
                {
                    var keys=new System.Collections.Generic.List<string>(dictionary.Keys); keys.Sort(StringComparer.Ordinal);
                    if (dictionary.ContainsKey("id")) { keys.Remove("id"); keys.Insert(0,"id"); }
                    var entries=new System.Collections.Generic.List<string>(); foreach(var key in keys) entries.Add(WriteJson(key)+":"+WriteJson(dictionary[key]));
                    return "{"+string.Join(",",entries.ToArray())+"}";
                }
                var array=value as System.Collections.Generic.List<object>;
                if(array != null) { var items=new System.Collections.Generic.List<string>(); foreach(var item in array) items.Add(WriteJson(item)); return "["+string.Join(",",items.ToArray())+"]"; }
                throw new InvalidOperationException("지원하지 않는 증거 JSON 값입니다.");
            }
        }
        public void Dispose()
        {
            if (!ReferenceEquals(_fixtureThread,Thread.CurrentThread)) throw new InvalidOperationException("원래 시험 thread에서만 Unity 정리를 수행합니다.");
            _disposeAttempted=true;
            try
            {
                try { if (_host != null) UnityEngine.Object.DestroyImmediate(_host); }
                finally
                {
                    if (Root != null && Directory.Exists(Root))
                    {
                        var root=Path.GetFullPath(Root); var temp=Path.GetFullPath(Path.GetTempPath());
                        Assert.That(root.StartsWith(temp,StringComparison.OrdinalIgnoreCase) && Path.GetFileName(root).StartsWith("AcadeGameMaker-C4-edit-",StringComparison.Ordinal) && (File.GetAttributes(root)&FileAttributes.ReparsePoint) == 0,Is.True);
                        Directory.Delete(root,true);
                    }
                    _rootRemoved=Root != null && !Directory.Exists(Root);
                }
            }
            catch (Exception error) { _disposeFailure=error; throw; }
        }
        private sealed class EnvironmentPort : IDesktopProfileLaunchEnvironmentV1
        {
            private readonly string _root;
            internal EnvironmentPort(string root) { _root=root; }
            public string GetPersistentDataPath() { return _root; }
            public DateTimeOffset GetUtcNow() { return DateTimeOffset.UtcNow; }
        }
    }
